// UpdateNewValues updates the mutable fields using the new values that were set on create except the ID field.
// Using this option is equivalent to using:
//
//	client.SubscriptionPeriod.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(subscriptionperiod.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *SubscriptionPeriodUpsertOne) UpdateNewValues() *SubscriptionPeriodUpsertOne {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		if _, exists := u.create.mutation.ID(); exists {
			s.SetIgnore(subscriptionperiod.FieldID)
		}
		if _, exists := u.create.mutation.CreatedAt(); exists {
			s.SetIgnore(subscriptionperiod.FieldCreatedAt)
		}
		if _, exists := u.create.mutation.SubscriptionID(); exists {
			s.SetIgnore(subscriptionperiod.FieldSubscriptionID)
		}
		if _, exists := u.create.mutation.Kind(); exists {
			s.SetIgnore(subscriptionperiod.FieldKind)
		}
		if _, exists := u.create.mutation.PlanCode(); exists {
			s.SetIgnore(subscriptionperiod.FieldPlanCode)
		}
		if _, exists := u.create.mutation.Interval(); exists {
			s.SetIgnore(subscriptionperiod.FieldInterval)
		}
		if _, exists := u.create.mutation.IdempotencyKey(); exists {
			s.SetIgnore(subscriptionperiod.FieldIdempotencyKey)
		}
	}))
	return u
}

